	for rows.Next() {
		var i ListChatTicketRunsRow
		if err := rows.Scan(
			&i.RunID,
			&i.MessageID,
			&i.State,
			&i.WaitReason,
			&i.StartedAt,
			&i.EndedAt,
			&i.CostUsdMicros,
			&i.TicketKey,
			&i.TicketTitle,
			&i.PrUrl,
			&i.AgentHandle,
			&i.StepsTotal,
			&i.StepsDone,
			&i.CurrentStep,
			&i.ActivityTool,
			&i.ActivityCommand,
			&i.ApprovalID,
			&i.ApprovalScope,
			&i.ApprovalAction,
			&i.ApprovalRisk,
			&i.ApprovalDetail,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
